import sys

def solve(n, a):
    total_sum = sum(a)
    if total_sum % 2 != 0:
        return [-1]

    target_sum = total_sum // 2
    a.sort(reverse=True)

    left_sum = 0
    left = []
    right = []

    for num in a:
        if left_sum + num <= target_sum:
            left.append(num)
            left_sum += num
        else:
            right.append(num)

    if len(left) == n and len(right) == n:
        return left + right
    else:
        return [-1]

def main():
    n = int(input())
    a = list(map(int, input().split()))

    result = solve(n, a)

    if result == [-1]:
        print(-1)
    else:
        print(*result)

